selector_to_html = {"a[href=\"https://en.wikipedia.org/wiki/Transformer_(deep_learning)\"]": "<img src=\"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Transformer%2C_full_architecture.png/330px-Transformer%2C_full_architecture.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail\" alt=\"Wikipedia thumbnail\" style=\"float:left; margin-right:10px;\"><p>In deep learning, the <b>transformer</b> is a family of artificial neural network architectures based on the multi-head attention mechanism, in which input data such as text, images, or audio, is converted to a sequence of numerical representations called tokens, and each token is converted into a vector via lookup from a word embedding table. At each layer, each token is then contextualized within the scope of the context window with other (unmasked) tokens via a parallel multi-head attention mechanism, allowing the signal for key tokens to be amplified and less important tokens to be diminished. Because self-attention alone is permutation-invariant, transformers inject positional information, typically through positional encodings or learned positional embeddings, so token order can affect the output.</p>", "a[href^=\"https://en.wikipedia.org/wiki/Transformer_(deep_learning)#\"]": "<img src=\"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Transformer%2C_full_architecture.png/330px-Transformer%2C_full_architecture.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail\" alt=\"Wikipedia thumbnail\" style=\"float:left; margin-right:10px;\"><p>In deep learning, the <b>transformer</b> is a family of artificial neural network architectures based on the multi-head attention mechanism, in which input data such as text, images, or audio, is converted to a sequence of numerical representations called tokens, and each token is converted into a vector via lookup from a word embedding table. At each layer, each token is then contextualized within the scope of the context window with other (unmasked) tokens via a parallel multi-head attention mechanism, allowing the signal for key tokens to be amplified and less important tokens to be diminished. Because self-attention alone is permutation-invariant, transformers inject positional information, typically through positional encodings or learned positional embeddings, so token order can affect the output.</p>", "a[href=\"https://en.wikipedia.org/wiki/BLEU\"]": "<p><b>BLEU</b> is an algorithm for evaluating the quality of text which has been machine-translated from one natural language to another. Quality is considered to be the correspondence between a machine's output and that of a human: \"the closer a machine translation is to a professional human translation, the better it is\" \u2013 this is the central idea behind BLEU.<sup class=\"plainlinks nourlexpansion citation\"></sup> Invented at IBM in 2001, BLEU was one of the first metrics to claim a high correlation with human judgements of quality,<sup class=\"plainlinks nourlexpansion citation\"></sup><sup class=\"plainlinks nourlexpansion citation\"></sup> and remains one of the most popular automated and inexpensive metrics.</p>", "a[href^=\"https://en.wikipedia.org/wiki/BLEU#\"]": "<p><b>BLEU</b> is an algorithm for evaluating the quality of text which has been machine-translated from one natural language to another. Quality is considered to be the correspondence between a machine's output and that of a human: \"the closer a machine translation is to a professional human translation, the better it is\" \u2013 this is the central idea behind BLEU.<sup class=\"plainlinks nourlexpansion citation\"></sup> Invented at IBM in 2001, BLEU was one of the first metrics to claim a high correlation with human judgements of quality,<sup class=\"plainlinks nourlexpansion citation\"></sup><sup class=\"plainlinks nourlexpansion citation\"></sup> and remains one of the most popular automated and inexpensive metrics.</p>", "a[href=\"https://en.wikipedia.org/wiki/Byte-pair_encoding\"]": "<p>In computing, <b>byte-pair encoding</b> (<b>BPE</b>), or <b>digram coding</b>, is an algorithm, first described in 1994 by Philip Gage, for encoding strings of text into smaller strings by creating and using a translation table. A slightly modified version of the algorithm is used in large language model tokenizers.</p>", "a[href^=\"https://en.wikipedia.org/wiki/Byte-pair_encoding#\"]": "<p>In computing, <b>byte-pair encoding</b> (<b>BPE</b>), or <b>digram coding</b>, is an algorithm, first described in 1994 by Philip Gage, for encoding strings of text into smaller strings by creating and using a translation table. A slightly modified version of the algorithm is used in large language model tokenizers.</p>", "a[href=\"https://en.wikipedia.org/wiki/Word2Vec\"]": "<p>In natural language processing, <b>Word2Vec</b> is a technique for obtaining vector representations of words. These vectors capture information about the meaning of the word based on the surrounding words, following the principles of distributional semantics. Once trained, the model can be used to find words with similar meanings or usage, while its embeddings can serve as inputs to systems for search and classification.</p>", "a[href^=\"https://en.wikipedia.org/wiki/Word2Vec#\"]": "<p>In natural language processing, <b>Word2Vec</b> is a technique for obtaining vector representations of words. These vectors capture information about the meaning of the word based on the surrounding words, following the principles of distributional semantics. Once trained, the model can be used to find words with similar meanings or usage, while its embeddings can serve as inputs to systems for search and classification.</p>", "a[href=\"https://en.wikipedia.org/wiki/ROUGE_(metric)\"]": "<p><b>ROUGE</b>, or <b>Recall-Oriented Understudy for Gisting Evaluation</b>, is a set of metrics and a software package used for evaluating automatic summarization and machine translation software in natural language processing. The metrics compare an automatically produced summary or translation against a reference or a set of references (human-produced) summary or translation. ROUGE metrics range between 0 and 1, with higher scores indicating higher similarity between the automatically produced summary and the reference.</p>", "a[href^=\"https://en.wikipedia.org/wiki/ROUGE_(metric)#\"]": "<p><b>ROUGE</b>, or <b>Recall-Oriented Understudy for Gisting Evaluation</b>, is a set of metrics and a software package used for evaluating automatic summarization and machine translation software in natural language processing. The metrics compare an automatically produced summary or translation against a reference or a set of references (human-produced) summary or translation. ROUGE metrics range between 0 and 1, with higher scores indicating higher similarity between the automatically produced summary and the reference.</p>", "a[href=\"https://doi.org/10.1145/3442188.3445922\"]": "\n<div>\n    <h3>On the Dangers of Stochastic Parrots</h3>\n    \n    <p><b>Authors:</b> Emily M. Bender, Timnit Gebru, Angelina McMillan-Major, Shmargaret Shmitchell</p>\n    \n    <p><b>Publisher:</b> ACM</p>\n    <p><b>Published:</b> 2021-3-2</p>\n</div>", "a[href=\"#fine-tuning-tutorial\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Fine tuning tutorial<a class=\"headerlink\" href=\"#fine-tuning-tutorial\" title=\"Link to this heading\">\u00b6</a></h1><h2>Overview<a class=\"headerlink\" href=\"#overview\" title=\"Link to this heading\">\u00b6</a></h2><p><strong>Adapting large language models</strong></p><p>Large language models (LLMs) are now ubiquitous in many applications and a\nvariety of both open- and closed-weight are available for many disparate tasks.\nHowever, it can be the case that an off-the-shelf model does not perform well\nin a specific task, or that we would like a smaller model focused on some\nspecific use cases and avoid expensive, large general-purpose models. In these\ncases, we need to find a way to \u201ctweak\u201d the behaviour of a model to fit the\nrequirements.\nA LLM can be adapted to a task in several ways: we can change the\ninstructions given to the model, provide external information at inference\ntime, or continue training the model on examples of the desired behaviour.</p>", "a[href=\"#a-minimal-fine-tuning-workflow\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">A minimal fine-tuning workflow<a class=\"headerlink\" href=\"#a-minimal-fine-tuning-workflow\" title=\"Link to this heading\">\u00b6</a></h3><p>A fine-tuning project can be organized as the following sequence:</p>", "a[href=\"#quantisation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Quantisation<a class=\"headerlink\" href=\"#quantisation\" title=\"Link to this heading\">\u00b6</a></h2><p>Large language models require substantial memory because they contain many\nparameters. Reducing the numerical precision used to represent those\nparameters can make a model easier to load, serve, and sometimes fine-tune.</p><p>This process is called <strong>quantisation</strong>.</p>", "a[href=\"#numerical-formats\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Numerical formats<a class=\"headerlink\" href=\"#numerical-formats\" title=\"Link to this heading\">\u00b6</a></h3><p>The names FP32, FP16, BF16, INT8, and 4-bit describe families of numerical\nrepresentations.</p>", "a[href=\"#exercise-choose-the-first-intervention\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Exercise: Choose the first intervention<a class=\"headerlink\" href=\"#exercise-choose-the-first-intervention\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#learning-rate-and-warmup\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Learning rate and warmup<a class=\"headerlink\" href=\"#learning-rate-and-warmup\" title=\"Link to this heading\">\u00b6</a></h4><p>The learning rate controls the scale of optimizer updates. An excessively\nlarge learning rate may destabilize training or damage useful pretrained\nbehaviour. An excessively small learning rate may produce little adaptation\nwithin the available training time.</p><p>Warmup starts with a smaller learning rate and increases it during the early\npart of training. This can reduce instability before the optimizer has\nestablished useful parameter statistics.</p>", "a[href=\"#fp32\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">FP32<a class=\"headerlink\" href=\"#fp32\" title=\"Link to this heading\">\u00b6</a></h4><p>FP32 is a 32-bit floating-point format. It provides a wide range and relatively\nhigh precision, but requires four bytes per value.</p><p>FP32 was historically common for neural-network training. Modern accelerators\noften achieve substantially higher throughput with 16-bit formats while still\nretaining selected operations in FP32 where necessary for numerical\nstability.</p>", "a[href=\"#hardware-and-software-support\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Hardware and software support<a class=\"headerlink\" href=\"#hardware-and-software-support\" title=\"Link to this heading\">\u00b6</a></h3><p>Quantisation support is not determined only by the accelerator\u2019s ability to\nrepresent integers.</p><p>An end-to-end workflow depends on several components:</p>", "a[href=\"#automated-and-human-evaluation\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Automated and human evaluation<a class=\"headerlink\" href=\"#automated-and-human-evaluation\" title=\"Link to this heading\">\u00b6</a></h4><p>Automated checks work well when correctness can be defined precisely. Schema\nvalidation, exact field comparison, classification scores, citation matching,\nand retrieval recall are useful examples.</p><p>Human evaluation is needed when quality depends on context, usefulness, or\nspecialist judgment.</p>", "a[href=\"#evaluation-during-fine-tuning\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Evaluation during fine-tuning<a class=\"headerlink\" href=\"#evaluation-during-fine-tuning\" title=\"Link to this heading\">\u00b6</a></h3><p>Training loss answers a narrow question: how well does the current model\npredict the training targets?</p><p>It does not show whether the model generalizes to new examples, whether the\napplication has improved, or whether unrelated capabilities have degraded.</p>", "a[href=\"#why-not-use-one-token-per-word\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Why not use one token per word?<a class=\"headerlink\" href=\"#why-not-use-one-token-per-word\" title=\"Link to this heading\">\u00b6</a></h4><p>A word-level vocabulary is simple to imagine:</p>", "a[href=\"#exercise-count-lora-parameters\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Exercise: Count LoRA parameters<a class=\"headerlink\" href=\"#exercise-count-lora-parameters\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#query-key-dot-product\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Query-Key dot product<a class=\"headerlink\" href=\"#query-key-dot-product\" title=\"Link to this heading\">\u00b6</a></h4><p><img alt=\"\" src=\"_images/query-key-fat-ginger.png\"/></p><p>Compute the dot product with each query-key pair, to determine how well the key matches the query.\nWhere the queries and keys align, the dot product is larger.\nLower left dot products are masked, as we want the model to predict every next word during training. To prevent data leakage, future words should not influence previous ones.</p>", "a[href=\"#when-rag-is-worth-introducing\"]": "<h5 class=\"tippy-header\" style=\"margin-top: 0;\">When RAG is worth introducing<a class=\"headerlink\" href=\"#when-rag-is-worth-introducing\" title=\"Link to this heading\">\u00b6</a></h5><p>RAG is a strong candidate when the application depends on information that is\nprivate, frequently updated, too large to include in every prompt, or expected\nto be cited.</p><p>It is less useful when the problem contains no substantial knowledge-retrieval\ncomponent. If the task is to convert a known input into a fixed schema, adding\na vector database may introduce infrastructure without addressing the actual\nfailure.</p>", "a[href=\"#from-token-ids-to-embeddings\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">From token IDs to embeddings<a class=\"headerlink\" href=\"#from-token-ids-to-embeddings\" title=\"Link to this heading\">\u00b6</a></h3><p>A token ID is an integer label. The numerical distance between two token IDs\nhas no semantic meaning. Token ID 100 is not inherently more similar to token\nID 101 than it is to token ID 9000.</p><p>Before the transformer can process the tokens, the model maps every token ID\nto a vector. This operation is performed by an embedding layer.</p>", "a[href=\"#loss-and-perplexity-on-held-out-text\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Loss and perplexity on held-out text<a class=\"headerlink\" href=\"#loss-and-perplexity-on-held-out-text\" title=\"Link to this heading\">\u00b6</a></h4><p>The simplest measurement uses the training objective itself. The model is\ngiven text it has not been trained on, and we measure how much probability it\nassigns to each actual next token.</p><p>The average negative log-likelihood of these tokens is the <strong>loss</strong>. Its\nexponential is called <strong>perplexity</strong>:</p>", "a[href=\"#type-of-transformers\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Type of transformers<a class=\"headerlink\" href=\"#type-of-transformers\" title=\"Link to this heading\">\u00b6</a></h3><p>Transformer architectures are commonly grouped into three broad families.</p>", "a[href=\"#ways-to-evaluate-an-llm\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Ways to evaluate an LLM<a class=\"headerlink\" href=\"#ways-to-evaluate-an-llm\" title=\"Link to this heading\">\u00b6</a></h3><p>The methods below are ordered roughly from the most automatic to the most\nhuman. Each one answers a slightly different question.</p>", "a[href=\"#see-also\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">See also<a class=\"headerlink\" href=\"#see-also\" title=\"Link to this heading\">\u00b6</a></h2><p>These lessons were inspired / adapted from the excellent material developed by the Vienna scientific cluster (VSC) <a class=\"reference external\" href=\"https://gitlab.tuwien.ac.at/vsc-public/training/LLMs-on-supercomputers\">here</a> [License: CC BY-SA 4.0]. Moreover, the Hugging Face people published a guidebook of sorts based on their experience training SmolLM, which can be found <a class=\"reference external\" href=\"https://huggingface.co/spaces/HuggingFaceTB/smol-training-playbook#beyond-base-modelspost-training-in-2025\">here</a>.</p>", "a[href=\"#what-fine-tuning-changes\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">What fine-tuning changes<a class=\"headerlink\" href=\"#what-fine-tuning-changes\" title=\"Link to this heading\">\u00b6</a></h3><p>A pretrained language model contains parameters learned from a large\ncollection of training data. During fine-tuning, the model processes examples\nthat represent a more specific objective. Gradients computed from those\nexamples update some or all of the model parameters.</p><p>For supervised fine-tuning, an example commonly contains an input and a\ndesired response:</p>", "a[href=\"#does-quantisation-make-a-model-faster\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Does quantisation make a model faster?<a class=\"headerlink\" href=\"#does-quantisation-make-a-model-faster\" title=\"Link to this heading\">\u00b6</a></h3><p>Not necessarily.</p><p>Fewer bits reduce the storage occupied by each value and may reduce the amount\nof memory transferred when reading weights. This can improve performance when\ninference is limited by memory bandwidth.</p>", "a[href=\"#why-a-benchmark-score-is-not-intelligence\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Why a benchmark score is not intelligence<a class=\"headerlink\" href=\"#why-a-benchmark-score-is-not-intelligence\" title=\"Link to this heading\">\u00b6</a></h4><p>Benchmarks are useful, but a high score does not mean that a model \u201cknows\u201d or\n\u201cunderstands\u201d a subject in the way a person who passed the same exam would.\nThere are several reasons for this.</p>", "a[href=\"#position-in-the-sequence\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Position in the sequence<a class=\"headerlink\" href=\"#position-in-the-sequence\" title=\"Link to this heading\">\u00b6</a></h4><p>Attention alone does not inherently know whether one token comes before or\nafter another. The model must therefore include information about position.</p><p>The original transformer added positional encodings to token embeddings.\nModern architectures may use other methods, such as learned position\nembeddings or rotary position embeddings.</p>", "a[href=\"#exercise-estimate-parameter-memory\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Exercise: Estimate parameter memory<a class=\"headerlink\" href=\"#exercise-estimate-parameter-memory\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#exercise-decide-whether-to-fine-tune\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Exercise: Decide whether to fine-tune<a class=\"headerlink\" href=\"#exercise-decide-whether-to-fine-tune\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#id1\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Weight and activation quantisation<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">\u00b6</a></h4><p>Other methods quantise both weights and activations.</p><p>This can enable lower-precision arithmetic throughout more of the computation,\nbut activation distributions vary with the input and can contain outliers.\nMaintaining model quality can therefore be more difficult than for\nweight-only quantisation.</p>", "a[href=\"#why-evaluating-an-llm-is-hard\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Why evaluating an LLM is hard<a class=\"headerlink\" href=\"#why-evaluating-an-llm-is-hard\" title=\"Link to this heading\">\u00b6</a></h3><p>Consider the prompt \u201cSummarise this article in three sentences\u201d. There is no\nsingle correct summary. Two good summaries may share very few words, while a\npoor summary may copy many words from a good one.</p><p>The difficulty has several sources:</p>", "a[href=\"#id2\"]": "<figure class=\"align-default\" id=\"id2\">\n<img alt=\"_images/prompt_context.webp\" src=\"_images/prompt_context.webp\"/>\n<figcaption>\n<p><span class=\"caption-text\">In 2026, a good majority of AI engineering is just context engineering.</span><a class=\"headerlink\" href=\"#id2\" title=\"Link to this image\">\u00b6</a></p>\n<div class=\"legend\">\n<p>Image credit: <a class=\"reference external\" href=\"https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents\">Anthropic</a>.</p>\n</div>\n</figcaption>\n</figure>", "a[href=\"#typical-pitfalls\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Typical pitfalls<a class=\"headerlink\" href=\"#typical-pitfalls\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#poor-reproducibility\"]": "<h5 class=\"tippy-header\" style=\"margin-top: 0;\">Poor reproducibility<a class=\"headerlink\" href=\"#poor-reproducibility\" title=\"Link to this heading\">\u00b6</a></h5><p>The reported score depends on many choices besides the model:</p>", "a[href=\"#from-text-to-tokens\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">From text to tokens<a class=\"headerlink\" href=\"#from-text-to-tokens\" title=\"Link to this heading\">\u00b6</a></h3><p>The first step is tokenisation. A tokeniser divides the input into units\ncalled <strong>tokens</strong> and maps every token to an integer ID.</p><p>Tokens do not necessarily correspond to words. Depending on the tokeniser, a\ntoken may represent a complete word, part of a word, punctuation, whitespace,\nor another frequently occurring character sequence.</p>", "a[href=\"#how-can-we-influence-a-model\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">How can we influence a model?<a class=\"headerlink\" href=\"#how-can-we-influence-a-model\" title=\"Link to this heading\">\u00b6</a></h3><p>The progression from prompting to RAG to fine-tuning represents increasing\nsystem complexity.</p>", "a[href=\"#software-and-infrastructure\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Software and infrastructure<a class=\"headerlink\" href=\"#software-and-infrastructure\" title=\"Link to this heading\">\u00b6</a></h2><p>The conceptual parts of the lesson do not require a GPU. Exercises can be\ncompleted through discussion or using an existing model interface.</p><p>A later hands-on fine-tuning lesson may use the Hugging Face ecosystem,\nincluding Transformers, Datasets, TRL, PEFT, and Accelerate. Those\nimplementation details are deliberately kept separate from the conceptual\nmaterial in this lesson.</p>", "a[href=\"#exercise-attention-and-masking\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Exercise: Attention and masking<a class=\"headerlink\" href=\"#exercise-attention-and-masking\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#saving-and-deploying-adapters\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Saving and deploying adapters<a class=\"headerlink\" href=\"#saving-and-deploying-adapters\" title=\"Link to this heading\">\u00b6</a></h3><p>One advantage of LoRA is that the adapter is much smaller than the full base\nmodel.</p><p>The base model and adapter can be stored separately:</p>", "a[href=\"#qlora\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">QLoRA<a class=\"headerlink\" href=\"#qlora\" title=\"Link to this heading\">\u00b6</a></h3><p>QLoRA combines a quantised frozen base model with trainable LoRA adapters.</p><p>The base model is stored in a low-bit representation. The LoRA parameters,\ngradients, optimizer state, and selected computations use higher precision\nwhere required.</p>", "a[href=\"#choosing-an-adaptation-strategy-aka-when-not-to-fine-tune\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Choosing an adaptation strategy - aka when NOT to fine-tune<a class=\"headerlink\" href=\"#choosing-an-adaptation-strategy-aka-when-not-to-fine-tune\" title=\"Link to this heading\">\u00b6</a></h2><p>When an LLM application performs poorly, fine-tuning is rarely the first or\nonly possible response. The model may need clearer instructions, better\ncontext, access to external information, or a more suitable evaluation\nprocedure.</p><p>Prompt engineering, retrieval-augmented generation, and fine-tuning address\ndifferent sources of failure:</p>", "a[href=\"#training-pipeline\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Training pipeline<a class=\"headerlink\" href=\"#training-pipeline\" title=\"Link to this heading\">\u00b6</a></h3><p>When a LLM is first trained, three steps are usually involved:</p>", "a[href=\"#bf16\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">BF16<a class=\"headerlink\" href=\"#bf16\" title=\"Link to this heading\">\u00b6</a></h4><p>BF16 also uses 16 bits, but allocates its bits differently from FP16. BF16 has\napproximately the same numerical range as FP32 but less precision within that\nrange.</p><p>This makes BF16 attractive for training on supported accelerators. Its broad\nrange reduces some of the numerical difficulties associated with FP16.</p>", "a[href=\"#llm-as-a-judge\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">LLM-as-a-judge<a class=\"headerlink\" href=\"#llm-as-a-judge\" title=\"Link to this heading\">\u00b6</a></h4><p>A strong language model (the <em>judge</em>) is asked to evaluate the outputs of the\nmodel being tested. This approach has become very common because it combines\nsome of the flexibility of human evaluation with the speed of automatic\nmetrics.</p><p>The judge receives a prompt that usually contains:</p>", "a[href=\"#encoder-only-models\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Encoder-only models<a class=\"headerlink\" href=\"#encoder-only-models\" title=\"Link to this heading\">\u00b6</a></h4><p>An encoder-only model builds contextual representations using information\nfrom both sides of a token. This is useful when the model must understand an\nentire input rather than generate a continuation.</p><p>Encoder-only models are commonly associated with classification,\nnamed-entity recognition, semantic similarity, and extractive question\nanswering.</p>", "a[href=\"#self-attention\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Self-attention<a class=\"headerlink\" href=\"#self-attention\" title=\"Link to this heading\">\u00b6</a></h4><p>Self-attention allows the representation at one token position to incorporate\ninformation from other token positions in the same sequence.</p><p>For every token, an attention head computes three vectors:</p>", "a[href=\"#full-fine-tuning\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Full fine-tuning<a class=\"headerlink\" href=\"#full-fine-tuning\" title=\"Link to this heading\">\u00b6</a></h3><p>In full fine-tuning, every trainable parameter in the model is updated.</p><p>For a model with billions of parameters, this creates substantial resource\nrequirements. The device must hold the model weights, gradients, optimizer\nstate, activations, and temporary buffers used by the training operations. In\nparticular, the optimizer state can be particularly expensive, since an\noptimizer may maintain multiple values for every trainable parameter. The cost\nfor full fine-tuning is comparable to that of pretraining, since all parameters\nneed updating. Full fine-tuning also produces a complete new set of model\nweights. If several tasks require separate models, storage and deployment costs\ngrow quickly.</p>", "a[href=\"#quantisation-and-model-quality\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Quantisation and model quality<a class=\"headerlink\" href=\"#quantisation-and-model-quality\" title=\"Link to this heading\">\u00b6</a></h3><p>Quantisation replaces some parameter values with approximations. It can\ntherefore affect model output.</p><p>The effect is not uniform across models or tasks. A method that preserves\nquality for common conversational prompts may affect numerical reasoning,\ncode generation, multilingual text, or specialist terminology differently.</p>", "a[href=\"#training-duration\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Training duration<a class=\"headerlink\" href=\"#training-duration\" title=\"Link to this heading\">\u00b6</a></h4><p>More epochs expose the model to the training examples more times. This may\nimprove learning initially, but eventually increases the risk of overfitting.</p><p>A small dataset can be memorized quickly. The best checkpoint is not\nnecessarily the final checkpoint.</p>", "a[href=\"#what-qlora-does-not-save\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">What QLoRA does not save<a class=\"headerlink\" href=\"#what-qlora-does-not-save\" title=\"Link to this heading\">\u00b6</a></h4><p>QLoRA does not remove activation memory. The forward pass must still process\nthe hidden states through every model layer.</p><p>Long sequences and large per-device batches can therefore exhaust memory even\nwhen the base weights occupy relatively little space.</p>", "a[href=\"#add-retrieval-if-evidence-is-missing\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Add retrieval if evidence is missing<a class=\"headerlink\" href=\"#add-retrieval-if-evidence-is-missing\" title=\"Link to this heading\">\u00b6</a></h4><p>Inspect failed examples. If the model could answer correctly when given the\nright document passage, the problem points toward retrieval.</p><p>Evaluate whether the retrieval stage finds that passage. Do not evaluate only\nthe final prose.</p>", "a[href=\"#what-should-contribute-to-the-loss\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">What should contribute to the loss?<a class=\"headerlink\" href=\"#what-should-contribute-to-the-loss\" title=\"Link to this heading\">\u00b6</a></h4><p>For assistant-response training, the input conversation provides context while\nthe desired assistant response provides the prediction target.</p><p>A common approach masks user and system tokens in the labels:</p>", "a[href=\"#exercise-quantise-a-small-set-of-values\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Exercise: Quantise a small set of values<a class=\"headerlink\" href=\"#exercise-quantise-a-small-set-of-values\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#initial-and-contextual-representations\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Initial and contextual representations<a class=\"headerlink\" href=\"#initial-and-contextual-representations\" title=\"Link to this heading\">\u00b6</a></h4><p>The embedding-layer output is only the initial representation of a token. It\ndoes not yet express what the token means in a particular sentence.</p><p>Consider the word <code class=\"docutils literal notranslate\"><span class=\"pre\">mole</span></code>:</p>", "a[href=\"#tunables\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Tunables<a class=\"headerlink\" href=\"#tunables\" title=\"Link to this heading\">\u00b6</a></h4><p>The following hyperparameters need to be estimated when performing a LoRA:</p>", "a[href=\"#prompt-engineering\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Prompt engineering<a class=\"headerlink\" href=\"#prompt-engineering\" title=\"Link to this heading\">\u00b6</a></h4><p>Prompt engineering changes the model\u2019s input. It does not update the model\nparameters.</p><p>A prompt can specify the task, the intended reader, the required structure,\nthe available evidence, and what the model should do when it cannot answer.\nIt can also contain examples of suitable inputs and outputs.</p>", "a[href=\"#lesson-schedule\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Lesson schedule<a class=\"headerlink\" href=\"#lesson-schedule\" title=\"Link to this heading\">\u00b6</a></h2><p>A possible schedule for a three-hour lesson is:</p>", "a[href=\"#what-kind-and-how-much-data-do-i-need\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">What kind and how much data do I need?<a class=\"headerlink\" href=\"#what-kind-and-how-much-data-do-i-need\" title=\"Link to this heading\">\u00b6</a></h4><p>As it might be expected, there is no one-size-fits-all recipe for the type and\nquantity of data needed for fine-tuning, which can vary wildly based on task\nand base model size.</p><p>A general indication is that data should be as <em>representative</em> as possible,\ncovering the same variation found in real inputs. It should cover examples that\nare routine, difficult, ambiguous, or where the expected answer is \u201cI do not\nknow\u201d. Generally speaking, less good examples are better than many low-quality\nones (e.g. duplicates, inconsistent formatting, incorrect answers, etc.). As\nstated many times, good segregation between training, validation and test data\nis paramount.</p>", "a[href=\"#fine-tuning\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Fine-tuning<a class=\"headerlink\" href=\"#fine-tuning\" title=\"Link to this heading\">\u00b6</a></h3><p>Fine-tuning continues training a pretrained model on examples chosen for a\nparticular objective. It changes some or all of the model parameters (or,\nsometimes, introduce a few new ones altogether).</p><p><img alt=\"\" src=\"_images/use-finetuning.png\"/></p>", "a[href=\"#who-is-the-lesson-for\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Who is the lesson for?<a class=\"headerlink\" href=\"#who-is-the-lesson-for\" title=\"Link to this heading\">\u00b6</a></h2><p>The lesson is intended for researchers, research software engineers, and\ntechnical staff who want to understand how large language models can be\nadapted to specialist tasks.</p><p>The main focus is not on any particular model or software library (our example\nwill be, though). Instead, the lesson develops a conceptual framework that can\nbe applied when planning an LLM-based application or a fine-tuning experiment.</p>", "a[href=\"#instructor-s-guide\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Instructor\u2019s guide<a class=\"headerlink\" href=\"#instructor-s-guide\" title=\"Link to this heading\">\u00b6</a></h2><h3>Why we teach this lesson<a class=\"headerlink\" href=\"#why-we-teach-this-lesson\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#benchmarks\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Benchmarks<a class=\"headerlink\" href=\"#benchmarks\" title=\"Link to this heading\">\u00b6</a></h3><h4>What a benchmark is<a class=\"headerlink\" href=\"#what-a-benchmark-is\" title=\"Link to this heading\">\u00b6</a></h4><p>A benchmark is a fixed set of tasks with known answers, together with a\nscoring procedure. It works like a standardised exam: every model answers the\nsame questions and receives a score, usually accuracy.</p><p>Most benchmarks use the methods described above. Multiple-choice benchmarks\nuse exact match, coding benchmarks use unit tests, and some newer benchmarks\nuse an LLM judge.</p>", "a[href=\"#representative-data\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Representative data<a class=\"headerlink\" href=\"#representative-data\" title=\"Link to this heading\">\u00b6</a></h4><p>Representative data covers the variation expected in real inputs. It should\ninclude routine examples, difficult cases, ambiguous cases, long and short\ninputs, and examples where the correct response is to refuse or state that\ninformation is missing.</p><p>Repeatedly generating examples from one template may produce a large dataset\nwithout producing meaningful diversity.</p>", "a[href=\"#feed-forward-networks\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Feed-forward networks<a class=\"headerlink\" href=\"#feed-forward-networks\" title=\"Link to this heading\">\u00b6</a></h3><p>After attention has exchanged information between token positions, a\nfeed-forward network transforms the representation at each position.</p><p>A simplified feed-forward operation is:</p>", "a[href=\"#per-channel-quantisation\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Per-channel quantisation<a class=\"headerlink\" href=\"#per-channel-quantisation\" title=\"Link to this heading\">\u00b6</a></h4><p>Per-channel quantisation uses a separate scale for each output channel or\nanother selected dimension.</p><p>This can better represent channels whose weights have different\ndistributions, at the cost of storing more scaling information and using a\nmore complicated kernel.</p>", "a[href=\"#weight-only-quantisation\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Weight-only quantisation<a class=\"headerlink\" href=\"#weight-only-quantisation\" title=\"Link to this heading\">\u00b6</a></h4><p>Weight-only quantisation stores model weights in a lower-bit format.\nActivations may remain in FP16, BF16, or another floating-point format.</p><p>This can reduce the memory needed to load the model and the memory bandwidth\nneeded to read its parameters. During computation, a kernel may dequantise\nweight blocks into a computation format or incorporate the scaling directly\ninto the matrix multiplication.</p>", "a[href=\"#other-practical-aspects\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Other practical aspects<a class=\"headerlink\" href=\"#other-practical-aspects\" title=\"Link to this heading\">\u00b6</a></h3><p>Before teaching the lesson, instructors should decide how far to go into the\nattention calculation. The important distinction is between:</p>", "a[href=\"#brittleness\"]": "<h5 class=\"tippy-header\" style=\"margin-top: 0;\">Brittleness<a class=\"headerlink\" href=\"#brittleness\" title=\"Link to this heading\">\u00b6</a></h5><p>Benchmark performance can depend on surface details. A model may answer a\nquestion correctly in one phrasing and fail when the question is reworded or\nthe answer options are reordered. A score on a fixed set of phrasings may\noverestimate how reliably the model handles the underlying skill.</p>", "a[href=\"#quick-reference\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Quick Reference<a class=\"headerlink\" href=\"#quick-reference\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#exercise-design-a-quantisation-benchmark\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Exercise: Design a quantisation benchmark<a class=\"headerlink\" href=\"#exercise-design-a-quantisation-benchmark\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#weight-and-activation-quantisation\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Weight and activation quantisation<a class=\"headerlink\" href=\"#weight-and-activation-quantisation\" title=\"Link to this heading\">\u00b6</a></h3><p>A quantisation method may target different parts of the computation.</p>", "a[href=\"#a-concrete-interpretation\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">A concrete interpretation<a class=\"headerlink\" href=\"#a-concrete-interpretation\" title=\"Link to this heading\">\u00b6</a></h4><p>Suppose the model processes:</p>", "a[href=\"#post-training-quantisation\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Post-training quantisation<a class=\"headerlink\" href=\"#post-training-quantisation\" title=\"Link to this heading\">\u00b6</a></h3><p>Post-training quantisation starts from an already trained model and converts\nsome of its values into a lower-precision representation.</p><p>No further task-specific training is necessarily required.</p>", "a[href=\"#timing\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Timing<a class=\"headerlink\" href=\"#timing\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#evaluating-in-languages-other-than-english\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Evaluating in languages other than English<a class=\"headerlink\" href=\"#evaluating-in-languages-other-than-english\" title=\"Link to this heading\">\u00b6</a></h3><p>Most evaluation resources were built for English. Evaluating a model in\nanother language, such as Swedish, adds some specific difficulties:</p>", "a[href=\"#what-problem-does-rag-solve\"]": "<h5 class=\"tippy-header\" style=\"margin-top: 0;\">What problem does RAG solve?<a class=\"headerlink\" href=\"#what-problem-does-rag-solve\" title=\"Link to this heading\">\u00b6</a></h5><p>RAG is appropriate when the model cannot answer reliably from its existing\nparameters and the required information exists in an external collection.</p><p>Typical collections include internal documentation, scientific papers,\ntechnical manuals, organizational policies, support records, and databases\nwhose contents change over time.</p>", "a[href=\"#consider-fine-tuning-for-persistent-behaviour\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Consider fine-tuning for persistent behaviour<a class=\"headerlink\" href=\"#consider-fine-tuning-for-persistent-behaviour\" title=\"Link to this heading\">\u00b6</a></h4><p>Fine-tuning becomes reasonable when the system has appropriate instructions\nand evidence but still fails in a repeated, measurable way.</p><p>At that point, the training examples can target a stable behaviour rather than\ncompensating for an undefined prompt or missing source.</p>", "a[href=\"#sequence-length\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Sequence length<a class=\"headerlink\" href=\"#sequence-length\" title=\"Link to this heading\">\u00b6</a></h4><p>Sequence length has a strong effect on memory and runtime. Longer sequences\nrequire more activation memory, and standard dense attention forms a\nquadratic attention matrix.</p><p>A batch size that works for short examples may fail when the batch contains\nlong examples.</p>", "a[href=\"#build-a-prompt-baseline\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Build a prompt baseline<a class=\"headerlink\" href=\"#build-a-prompt-baseline\" title=\"Link to this heading\">\u00b6</a></h4><p>Create the simplest prompt that specifies the task, context, constraints,\noutput, and abstention behaviour. Include examples where they clarify the\ndesired mapping.</p><p>Run the evaluation set and record the results. This baseline provides evidence\nagainst which retrieval or fine-tuning can be compared.</p>", "a[href=\"#when-prompting-is-enough\"]": "<h5 class=\"tippy-header\" style=\"margin-top: 0;\">When prompting is enough<a class=\"headerlink\" href=\"#when-prompting-is-enough\" title=\"Link to this heading\">\u00b6</a></h5><p>Prompt engineering is often sufficient when the base model already has the\nrequired capability and all necessary information can be included in the\ncontext.</p><p>Examples include rewriting text for a known audience, extracting fields from\na short document, producing a specified format, explaining supplied material,\nor generating a first draft that will be reviewed by a person.</p>", "a[href=\"#reading-a-benchmark-result\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Reading a benchmark result<a class=\"headerlink\" href=\"#reading-a-benchmark-result\" title=\"Link to this heading\">\u00b6</a></h4><p>When you see a benchmark score, it helps to ask:</p>", "a[href=\"#inside-a-transformer-block\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Inside a transformer block<a class=\"headerlink\" href=\"#inside-a-transformer-block\" title=\"Link to this heading\">\u00b6</a></h3><p>A transformer contains a stack of repeated blocks. Although details differ\nbetween model families, each block contains two major computational\ncomponents:</p>", "a[href=\"#verifiable-checks\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Verifiable checks<a class=\"headerlink\" href=\"#verifiable-checks\" title=\"Link to this heading\">\u00b6</a></h4><p>For some tasks, correctness can be checked by a program rather than by\ncomparing text.</p><p>Examples include:</p>", "a[href=\"#low-rank-adaptation\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Low-rank adaptation<a class=\"headerlink\" href=\"#low-rank-adaptation\" title=\"Link to this heading\">\u00b6</a></h3><p>Suppose a pretrained layer contains a weight matrix:</p>", "a[href=\"#evaluate-rag-in-parts\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Evaluate RAG in parts<a class=\"headerlink\" href=\"#evaluate-rag-in-parts\" title=\"Link to this heading\">\u00b6</a></h4><p>A RAG system has at least three evaluation targets:</p>", "a[href=\"#why-we-teach-this-lesson\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Why we teach this lesson<a class=\"headerlink\" href=\"#why-we-teach-this-lesson\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#evaluate-fine-tuning-against-meaningful-baselines\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Evaluate fine-tuning against meaningful baselines<a class=\"headerlink\" href=\"#evaluate-fine-tuning-against-meaningful-baselines\" title=\"Link to this heading\">\u00b6</a></h4><p>A fine-tuned model should be compared with the unchanged base model using the\nbest prompt developed during exploration.</p><p>Depending on the application, the comparison may also include:</p>", "a[href=\"#integer-and-low-bit-representations\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Integer and low-bit representations<a class=\"headerlink\" href=\"#integer-and-low-bit-representations\" title=\"Link to this heading\">\u00b6</a></h4><p>An 8-bit or 4-bit quantised representation provides far fewer possible bit\npatterns than a 16-bit floating-point representation.</p><p>The model therefore cannot retain every original value exactly. Quantisation\nmaps a set of high-precision values onto a smaller set of representable\nvalues.</p>", "a[href=\"#optimising-for-the-score\"]": "<h5 class=\"tippy-header\" style=\"margin-top: 0;\">Optimising for the score<a class=\"headerlink\" href=\"#optimising-for-the-score\" title=\"Link to this heading\">\u00b6</a></h5><p>When a benchmark becomes important, developers are tempted to optimise for it\ndirectly, for example by training on similar questions. This is an example of\nGoodhart\u2019s law: when a measure becomes a target, it stops being a good\nmeasure. Public leaderboards have had to replace their benchmarks for this\nreason.</p>", "a[href=\"#compute-dtype-and-storage-dtype\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Compute dtype and storage dtype<a class=\"headerlink\" href=\"#compute-dtype-and-storage-dtype\" title=\"Link to this heading\">\u00b6</a></h3><p>A QLoRA configuration commonly distinguishes between the format used to store\nthe quantised weights and the format used for computation.</p><p>For example:</p>", "a[href=\"#quantisation-during-fine-tuning\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Quantisation during fine-tuning<a class=\"headerlink\" href=\"#quantisation-during-fine-tuning\" title=\"Link to this heading\">\u00b6</a></h3><p>Fine-tuning requires much more memory than inference because training needs\nadditional state.</p><p>A rough decomposition is:</p>", "a[href=\"#fine-tuning-large-language-models\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Fine-tuning large language models<a class=\"headerlink\" href=\"#fine-tuning-large-language-models\" title=\"Link to this heading\">\u00b6</a></h2><p>Fine-tuning continues the training of a pretrained model using examples\nselected for a particular task or behaviour.</p><p>Unlike prompt engineering and retrieval-augmented generation, fine-tuning\nchanges model parameters. The resulting behaviour is encoded in a new set of\nweights or in a smaller set of adapter parameters.</p>", "a[href=\"#task-evaluation\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Task evaluation<a class=\"headerlink\" href=\"#task-evaluation\" title=\"Link to this heading\">\u00b6</a></h4><p>The evaluation should match the intended behaviour.</p><p>For structured output, measure whether the response parses and whether the\nfields are correct. For classification, use suitable class-level metrics. For\nsummarization or open-ended generation, combine human review with checks for\nrequired content, unsupported claims, format adherence, and omissions.</p>", "a[href=\"#saturation\"]": "<h5 class=\"tippy-header\" style=\"margin-top: 0;\">Saturation<a class=\"headerlink\" href=\"#saturation\" title=\"Link to this heading\">\u00b6</a></h5><p>When most strong models score above 90% on a benchmark, the remaining\ndifferences are small and often within noise. The benchmark no longer\nseparates good models from very good ones. This has happened to several\npopular benchmarks, which is why harder replacements keep being created.</p>", "a[href=\"#encoder-decoder-models\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Encoder-decoder models<a class=\"headerlink\" href=\"#encoder-decoder-models\" title=\"Link to this heading\">\u00b6</a></h4><p>An encoder-decoder model first builds representations of the input with an\nencoder. A decoder then generates an output while attending to both the\nalready generated output and the encoded input.</p><p>This architecture is well suited for sequence-to-sequence tasks such as\ntranslation and summarization. They are also used for\nmultimodal tasks such as image segmentation (for eg., Detectron) and generation (for eg., Stable Diffusion).</p>", "a[href=\"#the-key-value-cache\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">The key-value cache<a class=\"headerlink\" href=\"#the-key-value-cache\" title=\"Link to this heading\">\u00b6</a></h4><p>Autoregressive generation stores keys and values from previous tokens so that\nthe model does not recompute the complete sequence at every generation step.\nThis storage is called the <strong>key-value cache</strong>, or KV cache.</p><p>The KV cache grows with sequence length, batch size, number of layers, and the\nrelevant attention dimensions. For long contexts or large batches, it may\nconsume a substantial fraction of inference memory.</p>", "a[href=\"#quantisation-aware-training\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Quantisation-aware training<a class=\"headerlink\" href=\"#quantisation-aware-training\" title=\"Link to this heading\">\u00b6</a></h3><p>Quantisation-aware training simulates low-precision effects during training.\nThe optimization process can then adjust the model parameters to compensate\nfor some of the approximation introduced by quantisation.</p><p>A simplified view is:</p>", "a[href=\"#why-tokenisation-matters\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Why tokenisation matters<a class=\"headerlink\" href=\"#why-tokenisation-matters\" title=\"Link to this heading\">\u00b6</a></h4><p>Tokenisation affects the length of the sequence seen by the model. This in\nturn affects memory use, computation, and the amount of text that fits within\nthe context window.</p><p>It can also affect performance across languages and specialist domains. A\ntokeniser may represent frequent English words efficiently while dividing a\nscientific term or a word from another language into many small fragments.\nThe model can still process such text, but the representation uses more\npositions and may have been encountered less often during training.</p>", "a[href=\"#choosing-whether-to-quantise\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Choosing whether to quantise<a class=\"headerlink\" href=\"#choosing-whether-to-quantise\" title=\"Link to this heading\">\u00b6</a></h3><p>Quantisation is useful when model-weight memory is a meaningful constraint.</p><p>For inference, this may be the case when the model does not fit on the\navailable accelerator, when several model replicas are needed, or when memory\nbandwidth limits throughput.</p>", "a[href=\"#learning-objectives\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Learning objectives<a class=\"headerlink\" href=\"#learning-objectives\" title=\"Link to this heading\">\u00b6</a></h2><p>By the end of the lesson, learners should be able to:</p>", "a[href=\"#from-representations-to-token-probabilities\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">From representations to token probabilities<a class=\"headerlink\" href=\"#from-representations-to-token-probabilities\" title=\"Link to this heading\">\u00b6</a></h3><p>After the final transformer block, the model converts the representation at\nthe relevant sequence position into one score for every token in the\nvocabulary. These scores are called <strong>logits</strong>.</p><p>Softmax turns the logits into a probability distribution:</p>", "a[href=\"#why-numerical-precision-matters\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Why numerical precision matters<a class=\"headerlink\" href=\"#why-numerical-precision-matters\" title=\"Link to this heading\">\u00b6</a></h3><p>Neural-network parameters are numerical values. A numerical format determines\nwhich values can be represented and how much memory is required to store each\none.</p><p>A model containing seven billion parameters requires approximately 28 GB to\nstore its weights in 32-bit precision:</p>", "a[href=\"#evaluate-more-than-fluency\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Evaluate more than fluency<a class=\"headerlink\" href=\"#evaluate-more-than-fluency\" title=\"Link to this heading\">\u00b6</a></h4><p>A response can sound better without becoming more correct. Evaluation should\ntherefore separate dimensions that matter to the application.</p><p>For a document question-answering system, useful dimensions might include\nfactual support, citation correctness, completeness, appropriate abstention,\nlatency, and cost.</p>", "a[href=\"#establish-the-task-and-evaluation\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Establish the task and evaluation<a class=\"headerlink\" href=\"#establish-the-task-and-evaluation\" title=\"Link to this heading\">\u00b6</a></h4><p>Write down what a satisfactory output looks like. Assemble examples that\ncover ordinary cases, difficult cases, ambiguous cases, and cases where the\nsystem should decline to answer.</p><p>The evaluation need not initially be large. It does need to be representative\nenough to expose whether a change solves the intended problem.</p>", "a[href=\"#regression-evaluation\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Regression evaluation<a class=\"headerlink\" href=\"#regression-evaluation\" title=\"Link to this heading\">\u00b6</a></h4><p>Fine-tuning may improve the target task while changing other behaviour.</p><p>A regression set should cover important capabilities that the adapted model\nmust retain. This may include general instruction following, multilingual\ninputs, code formatting, safety constraints, or appropriate abstention.</p>", "a[href=\"#per-tensor-quantisation\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Per-tensor quantisation<a class=\"headerlink\" href=\"#per-tensor-quantisation\" title=\"Link to this heading\">\u00b6</a></h4><p>Per-tensor quantisation uses one scale for the complete tensor.</p><p>This keeps the representation simple, but a few unusually large or small\nvalues can determine the range for every other value. The available levels may\nthen be used inefficiently for most of the tensor.</p>", "a[href=\"#a-practical-decision-process\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">A practical decision process<a class=\"headerlink\" href=\"#a-practical-decision-process\" title=\"Link to this heading\">\u00b6</a></h3><p>The adaptation decision begins with a failure analysis rather than a choice of\ntechnology.</p>", "a[href=\"#when-full-fine-tuning-may-be-justified\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">When full fine-tuning may be justified<a class=\"headerlink\" href=\"#when-full-fine-tuning-may-be-justified\" title=\"Link to this heading\">\u00b6</a></h4><p>Full fine-tuning offers the greatest flexibility because updates are not\nrestricted to selected components. It may be appropriate when the task\nrequires broad changes, the training dataset is sufficiently large, and the\nproject has the compute and evaluation capacity to manage the resulting\nmodel.</p><p>These conditions are demanding. For many organizational and workshop use\ncases, parameter-efficient fine-tuning is the more practical starting point.</p>", "a[href=\"#evaluating-large-language-models\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Evaluating large language models<a class=\"headerlink\" href=\"#evaluating-large-language-models\" title=\"Link to this heading\">\u00b6</a></h2><p>Once a model has been trained, whether through the full training pipeline or\nthrough our own fine-tuning, we need to answer a simple question: is it any\ngood?</p><p>For many machine learning models, this question has a fairly direct answer. An\nimage classifier is compared with the correct labels, and accuracy summarises\nthe result. A generative language model is harder to assess. Its output is\nfree text, many different answers can be correct, and \u201cgood\u201d can mean\naccurate, helpful, concise, safe, or well written, depending on who is asking.</p>", "a[href=\"#parameter-efficient-fine-tuning\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Parameter-efficient fine-tuning<a class=\"headerlink\" href=\"#parameter-efficient-fine-tuning\" title=\"Link to this heading\">\u00b6</a></h3><p>Parameter-efficient fine-tuning (PEFT) keeps most pretrained parameters\nfrozen and learns a much smaller set of task-specific parameters.</p><p>The base model still participates in every forward pass. Freezing the base\nmodel does not remove the need to load it or execute its layers. The main\ntraining savings come from not storing gradients and optimizer states for all\nbase-model parameters.</p>", "a[href=\"#symmetric-and-asymmetric-quantisation\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Symmetric and asymmetric quantisation<a class=\"headerlink\" href=\"#symmetric-and-asymmetric-quantisation\" title=\"Link to this heading\">\u00b6</a></h4><p>In symmetric quantisation, the representable range is centered around zero.\nThe zero point is therefore zero or fixed by the representation.</p><p>In asymmetric quantisation, both a scale and a non-zero offset may be used.\nThis can represent distributions that are not centered around zero more\nefficiently, at the cost of additional complexity.</p>", "a[href=\"#exercise-trace-information-through-the-model\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Exercise: Trace information through the model<a class=\"headerlink\" href=\"#exercise-trace-information-through-the-model\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#what-qlora-saves\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">What QLoRA saves<a class=\"headerlink\" href=\"#what-qlora-saves\" title=\"Link to this heading\">\u00b6</a></h4><p>QLoRA primarily reduces the memory occupied by the frozen base-model weights.</p><p>LoRA already avoids storing gradients and optimizer states for those frozen\nweights. Quantisation further reduces their storage.</p>", "a[href=\"#combining-rag-and-fine-tuning\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Combining RAG and fine-tuning<a class=\"headerlink\" href=\"#combining-rag-and-fine-tuning\" title=\"Link to this heading\">\u00b6</a></h3><p>RAG and fine-tuning are not mutually exclusive.</p><p>A useful division of labour is that RAG supplies the evidence, whereas\nfine-tuning teaches the model how to use it.</p>", "a[href=\"#reference-based-metrics\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Reference-based metrics<a class=\"headerlink\" href=\"#reference-based-metrics\" title=\"Link to this heading\">\u00b6</a></h4><p>When a reference answer exists, the generated output can be compared with it\nautomatically.</p>", "a[href=\"#why-does-a-low-rank-update-help\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Why does a low-rank update help?<a class=\"headerlink\" href=\"#why-does-a-low-rank-update-help\" title=\"Link to this heading\">\u00b6</a></h4><p>Fine-tuning does not necessarily require an independent change in every\ndirection of a large weight matrix. For many adaptation tasks, a lower\ndimensional update can provide enough capacity to shift the model\u2019s\nbehaviour.</p><p>LoRA makes this assumption explicit by restricting the update to a matrix\nwhose rank is at most (r).</p>", "a[href=\"#human-evaluation\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Human evaluation<a class=\"headerlink\" href=\"#human-evaluation\" title=\"Link to this heading\">\u00b6</a></h4><p>People read the model\u2019s outputs and rate them. Raters may give a score on a\nscale, compare two responses, or mark specific errors.</p><p>Good human evaluation uses a written rubric that defines what each score\nmeans, and separates dimensions such as correctness, helpfulness, clarity, and\nsafety.</p>", "a[href=\"#what-a-benchmark-is\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">What a benchmark is<a class=\"headerlink\" href=\"#what-a-benchmark-is\" title=\"Link to this heading\">\u00b6</a></h4><p>A benchmark is a fixed set of tasks with known answers, together with a\nscoring procedure. It works like a standardised exam: every model answers the\nsame questions and receives a score, usually accuracy.</p><p>Most benchmarks use the methods described above. Multiple-choice benchmarks\nuse exact match, coding benchmarks use unit tests, and some newer benchmarks\nuse an LLM judge.</p>", "a[href=\"#what-is-a-large-language-model\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">What is a Large Language Model?<a class=\"headerlink\" href=\"#what-is-a-large-language-model\" title=\"Link to this heading\">\u00b6</a></h2><p>A Large Language Model (LLM) is a type of artificial intelligence trained on\nvast amounts of text data to predict and generate human-like text. At their\ncore, these models learn statistical patterns in language: given a sequence of\nwords (or better <em>tokens</em>: fragments of words, commas, and anything in text),\nthey predict what comes next.</p>", "a[href=\"#retrieval-augmented-generation\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Retrieval-augmented generation<a class=\"headerlink\" href=\"#retrieval-augmented-generation\" title=\"Link to this heading\">\u00b6</a></h4><p>Retrieval-augmented generation (RAG) adds an external\ninformation-retrieval stage.</p><p><img alt=\"\" src=\"_images/use-rag.png\"/></p>", "a[href=\"#human-preference-rankings\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Human preference rankings<a class=\"headerlink\" href=\"#human-preference-rankings\" title=\"Link to this heading\">\u00b6</a></h4><p>Preference rankings collect many pairwise human judgements at large scale.\nThe best-known example is LMArena (formerly Chatbot Arena). Users submit a\nprompt, receive answers from two anonymous models, and vote for the one they\nprefer. The votes are combined into a ranking using a rating system similar to\nthe Elo ratings used in chess.</p><p><strong>Useful for:</strong> comparing general-purpose chat models on realistic prompts.\nBecause the prompts come from real users rather than a fixed test set, the\nranking is harder to memorise.</p>", "a[href=\"#where-lora-adapters-are-placed\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Where LoRA adapters are placed<a class=\"headerlink\" href=\"#where-lora-adapters-are-placed\" title=\"Link to this heading\">\u00b6</a></h3><p>LoRA is applied to linear transformations in the model. Attention projections\nare common targets:</p>", "a[href=\"#when-not-to-fine-tune\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">When not to fine-tune<a class=\"headerlink\" href=\"#when-not-to-fine-tune\" title=\"Link to this heading\">\u00b6</a></h3><p>Fine-tuning is often proposed too early. Before training, it is worth checking\nwhether the proposed use case matches any of the following situations:</p>", "a[href=\"#evaluating-a-fine-tuned-model\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Evaluating a fine-tuned model<a class=\"headerlink\" href=\"#evaluating-a-fine-tuned-model\" title=\"Link to this heading\">\u00b6</a></h3><p>The methods in this section fit together when evaluating a model we have\nfine-tuned ourselves. The practical evaluation is described in\n<a class=\"reference internal\" href=\"#document-fine-tuning\"><span class=\"std std-doc\">fine-tuning large language models</span></a> and in\n<a class=\"reference internal\" href=\"#document-choosing-an-adaptation-strategy\"><span class=\"std std-doc\">choosing an adaptation strategy</span></a>. In\nsummary:</p>", "a[href=\"#preparing-exercises\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Preparing exercises<a class=\"headerlink\" href=\"#preparing-exercises\" title=\"Link to this heading\">\u00b6</a></h3><p>e.g. what to do the day before to set up common repositories.</p>", "a[href=\"#overview\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Overview<a class=\"headerlink\" href=\"#overview\" title=\"Link to this heading\">\u00b6</a></h2><p><strong>Adapting large language models</strong></p><p>Large language models (LLMs) are now ubiquitous in many applications and a\nvariety of both open- and closed-weight are available for many disparate tasks.\nHowever, it can be the case that an off-the-shelf model does not perform well\nin a specific task, or that we would like a smaller model focused on some\nspecific use cases and avoid expensive, large general-purpose models. In these\ncases, we need to find a way to \u201ctweak\u201d the behaviour of a model to fit the\nrequirements.\nA LLM can be adapted to a task in several ways: we can change the\ninstructions given to the model, provide external information at inference\ntime, or continue training the model on examples of the desired behaviour.</p>", "a[href=\"#contamination\"]": "<h5 class=\"tippy-header\" style=\"margin-top: 0;\">Contamination<a class=\"headerlink\" href=\"#contamination\" title=\"Link to this heading\">\u00b6</a></h5><p>LLMs are trained on very large collections of text from the internet.\nBenchmark questions and answers are often published online, so they can end\nup in the training data. A model may then answer correctly because it has\nseen the answer, not because it can solve the problem.</p><p>This is similar to a student who memorised last year\u2019s exam. Contamination is\ndifficult to rule out, because the training data of most models is not fully\ndisclosed.</p>", "a[href=\"#fp16\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">FP16<a class=\"headerlink\" href=\"#fp16\" title=\"Link to this heading\">\u00b6</a></h4><p>FP16 uses 16 bits per value. Compared with FP32, FP16 reduces both numerical\nrange and precision.</p><p>The reduced range can cause overflow or underflow during training. Mixed\nprecision training may therefore use loss scaling and retain some values or\noperations in FP32.</p>", "a[href=\"#comparing-the-methods\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Comparing the methods<a class=\"headerlink\" href=\"#comparing-the-methods\" title=\"Link to this heading\">\u00b6</a></h4><p>In practice, these methods are combined. Cheap automatic checks run often and\ncover the parts of the task that can be verified. Human evaluation, or an LLM\njudge validated against humans, covers the rest.</p>", "a[href=\"#exercise-diagnose-a-memory-bottleneck\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Exercise: Diagnose a memory bottleneck<a class=\"headerlink\" href=\"#exercise-diagnose-a-memory-bottleneck\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#interesting-questions-you-might-get\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Interesting questions you might get<a class=\"headerlink\" href=\"#interesting-questions-you-might-get\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#causal-masking\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Causal masking<a class=\"headerlink\" href=\"#causal-masking\" title=\"Link to this heading\">\u00b6</a></h4><p>During next-token training, a decoder-only model must not use future tokens to\npredict an earlier token.</p><p>Consider:</p>", "a[href=\"#from-values-to-attention\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">From values to attention<a class=\"headerlink\" href=\"#from-values-to-attention\" title=\"Link to this heading\">\u00b6</a></h4><p><img alt=\"\" src=\"_images/value-fat-ginger.png\"/></p><p>Value matrix multiplied by the embedding of the previous word results in the value vector</p>", "a[href=\"#multi-head-attention\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Multi-head attention<a class=\"headerlink\" href=\"#multi-head-attention\" title=\"Link to this heading\">\u00b6</a></h3><p>A transformer does not compute a single attention pattern. It computes\nseveral attention heads in parallel.</p><p>Each head has its own query, key, and value projections. This allows different\nheads to construct different patterns of information exchange. The outputs of\nthe heads are concatenated and passed through another learned projection.</p>", "a[href=\"#summary\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Summary<a class=\"headerlink\" href=\"#summary\" title=\"Link to this heading\">\u00b6</a></h3><p>Quantisation reduces the number of bits used to represent model values. This\ncan substantially reduce parameter storage and may improve inference\nperformance when suitable kernels and hardware support are available.</p><p>Lower precision introduces approximation error. The effect depends on more\nthan the nominal bit width. Scaling method, group size, treatment of outliers,\nquantised components, computation dtype, model architecture, and runtime\nimplementation all matter.</p>", "a[href=\"#in-context-learning\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">In-context learning<a class=\"headerlink\" href=\"#in-context-learning\" title=\"Link to this heading\">\u00b6</a></h3><p>In-context learning can be acheived by several methods.</p>", "a[href=\"#residual-connections-and-normalization\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Residual connections and normalization<a class=\"headerlink\" href=\"#residual-connections-and-normalization\" title=\"Link to this heading\">\u00b6</a></h3><p>A transformer block does not replace its input representation outright.\nResidual connections allow a sublayer to contribute an update:</p>", "a[href=\"#sidenote-context-length-and-computational-cost\"]": "<h5 class=\"tippy-header\" style=\"margin-top: 0;\">Sidenote: Context length and computational cost<a class=\"headerlink\" href=\"#sidenote-context-length-and-computational-cost\" title=\"Link to this heading\">\u00b6</a></h5><p>For standard dense attention, a sequence containing (n) tokens produces an\nattention-score matrix containing (n^2) entries for every head.</p><p>Doubling the sequence length therefore produces approximately four times as\nmany query-key comparisons. The total cost of a transformer also includes\nprojection and feed-forward operations, so end-to-end scaling is more\ncomplicated than one formula suggests. Nevertheless, the quadratic attention\nmatrix is an important reason why long contexts can be expensive. There are a\nfew tricks to mitigate this, such as <a class=\"reference external\" href=\"https://huggingface.co/blog/not-lain/kv-caching\">KV\ncaching</a>.</p>", "a[href=\"#comparing-queries-and-keys\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Comparing queries and keys<a class=\"headerlink\" href=\"#comparing-queries-and-keys\" title=\"Link to this heading\">\u00b6</a></h4><p>The model computes a dot product between each query and each key. A larger\ndot product means that the query and key are more strongly aligned in the\nlearned representation space.</p><p>The scaled dot-product attention operation is:</p>", "a[href=\"#evaluating-the-adaptation-ladder\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Evaluating the adaptation ladder<a class=\"headerlink\" href=\"#evaluating-the-adaptation-ladder\" title=\"Link to this heading\">\u00b6</a></h3><p>Evaluation should precede an increase in complexity: otherwise, there is no\nreliable way to tell whether the additional component helped.</p>", "a[href=\"#a-narrow-sample\"]": "<h5 class=\"tippy-header\" style=\"margin-top: 0;\">A narrow sample<a class=\"headerlink\" href=\"#a-narrow-sample\" title=\"Link to this heading\">\u00b6</a></h5><p>A benchmark covers a limited set of tasks, formats, and languages, often\nmultiple-choice questions in English. Your application is probably different.\nA model that ranks first on a general benchmark is not necessarily the best\nchoice for extracting fields from Swedish invoices.</p>", "a[href=\"#decoder-only-models\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Decoder-only models<a class=\"headerlink\" href=\"#decoder-only-models\" title=\"Link to this heading\">\u00b6</a></h4><p>A decoder-only model predicts the next token based on the tokens that precede\nit. Most contemporary general-purpose generative language models use this\narchitecture.</p><p>At each generation step, the model produces a probability distribution over\nthe vocabulary. A decoding procedure selects a token, appends it to the\nsequence, and invokes the model again.</p>", "a[href=\"#intended-learning-outcomes\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Intended learning outcomes<a class=\"headerlink\" href=\"#intended-learning-outcomes\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#packing\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Packing<a class=\"headerlink\" href=\"#packing\" title=\"Link to this heading\">\u00b6</a></h4><p>Packing places several short examples into one fixed-length training\nsequence. This reduces computation wasted on padding.</p><p>Without packing:</p>", "a[href=\"#group-wise-quantisation\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Group-wise quantisation<a class=\"headerlink\" href=\"#group-wise-quantisation\" title=\"Link to this heading\">\u00b6</a></h4><p>Group-wise quantisation divides weights into smaller groups and calculates a\nscale for each group.</p><p>This is a common compromise for low-bit model weights. Smaller groups usually\nreduce approximation error because each scale describes a more local range of\nvalues. They also require more metadata and may affect kernel efficiency.</p>", "a[href=\"#why-attention-projections-are-common-targets\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Why attention projections are common targets<a class=\"headerlink\" href=\"#why-attention-projections-are-common-targets\" title=\"Link to this heading\">\u00b6</a></h4><p>Attention projections determine how token representations are converted into\nqueries, keys, values, and attention outputs. Adapting those projections can\nchange which contextual relationships the model emphasizes and how\ninformation is exchanged between positions.</p><p>This makes attention projections a natural target for tasks that require a\nchange in how the model responds to context.</p>", "a[href=\"#training-configuration\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Training configuration<a class=\"headerlink\" href=\"#training-configuration\" title=\"Link to this heading\">\u00b6</a></h3><p>A training configuration controls both optimization and resource use.</p><p>The most visible parameters include learning rate, number of epochs, batch\nsize, gradient accumulation, maximum sequence length, evaluation frequency,\nand checkpoint frequency.</p>", "a[href=\"#quantisation-granularity\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Quantisation granularity<a class=\"headerlink\" href=\"#quantisation-granularity\" title=\"Link to this heading\">\u00b6</a></h3><p>A tensor does not need to share one scale across all of its values. The scale\ncan be calculated at different levels of granularity.</p>", "a[href=\"#batch-size-and-gradient-accumulation\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Batch size and gradient accumulation<a class=\"headerlink\" href=\"#batch-size-and-gradient-accumulation\" title=\"Link to this heading\">\u00b6</a></h4><p>The per-device batch size is the number of examples processed by one device\nin one forward and backward pass.</p><p>Gradient accumulation performs several such passes before applying an\noptimizer step. With data-parallel training, the effective batch size is:</p>", "a[href=\"#anatomy-of-a-large-language-model\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Anatomy of a Large Language Model<a class=\"headerlink\" href=\"#anatomy-of-a-large-language-model\" title=\"Link to this heading\">\u00b6</a></h2><p>A language model does not read text as words and sentences: text must first be\nconverted into numerical representations, then transformer layers update\nthose representations using the surrounding context.</p><p>A simplified forward pass looks like this:</p>", "a[href=\"#validation-loss\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Validation loss<a class=\"headerlink\" href=\"#validation-loss\" title=\"Link to this heading\">\u00b6</a></h4><p>Validation loss applies the same token-prediction objective to examples that\nwere not used for parameter updates.</p><p>If training loss continues to fall while validation loss stops improving or\nbegins to rise, overfitting is a possible explanation.</p>", "a[href=\"#preparing-fine-tuning-data\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Preparing fine-tuning data<a class=\"headerlink\" href=\"#preparing-fine-tuning-data\" title=\"Link to this heading\">\u00b6</a></h3><p>A fine-tuning dataset should represent the behaviour expected in deployment.</p><p>For an instruction-tuned chat model, examples are often represented as\nmessages:</p>", "a[href=\"#common-benchmark-families\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Common benchmark families<a class=\"headerlink\" href=\"#common-benchmark-families\" title=\"Link to this heading\">\u00b6</a></h4><p>The table lists a few well-known examples. It is not a complete list, and new\nbenchmarks appear frequently.</p>", "a[href=\"#scale-and-zero-point\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Scale and zero point<a class=\"headerlink\" href=\"#scale-and-zero-point\" title=\"Link to this heading\">\u00b6</a></h3><p>A common integer quantisation scheme maps a real-valued tensor (x) to an\ninteger tensor (q).</p><p>A simplified mapping is:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
